package matteroverdrive.menu;
import matteroverdrive.blockentity.ContractMarketBlockEntity;import matteroverdrive.registry.ModBlocks;import matteroverdrive.registry.ModMenus;import net.minecraft.core.BlockPos;import net.minecraft.network.FriendlyByteBuf;import net.minecraft.world.entity.player.Inventory;import net.minecraft.world.entity.player.Player;import net.minecraft.world.inventory.*;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraftforge.items.SlotItemHandler;
public class ContractMarketMenu extends AbstractContainerMenu{private final ContractMarketBlockEntity market;public ContractMarketMenu(int id,Inventory inv,FriendlyByteBuf buf){this(id,inv,find(inv,buf.readBlockPos()));}public ContractMarketMenu(int id,Inventory inv,ContractMarketBlockEntity market){super(ModMenus.CONTRACT_MARKET.get(),id);this.market=market;for(int i=0;i<3;i++)addSlot(new SlotItemHandler(market.getOffers(),i,44+i*36,38));for(int r=0;r<3;r++)for(int c=0;c<9;c++)addSlot(new Slot(inv,c+r*9+9,8+c*18,90+r*18));for(int c=0;c<9;c++)addSlot(new Slot(inv,c,8+c*18,148));}private static ContractMarketBlockEntity find(Inventory inv,BlockPos pos){BlockEntity be=inv.player.level().getBlockEntity(pos);return be instanceof ContractMarketBlockEntity market?market:new ContractMarketBlockEntity(pos,ModBlocks.get("contract_market").get().defaultBlockState());}@Override public boolean stillValid(Player player){return stillValid(ContainerLevelAccess.create(player.level(),market.getBlockPos()),player,ModBlocks.get("contract_market").get());}@Override public ItemStack quickMoveStack(Player player,int index){return ItemStack.EMPTY;}}